add(S,'Линейное уравнение','ОГЭ','Решите уравнение 3x − 7 = 8.','x = 5','Переносим −7 в правую часть: 3x = 8 + 7 = 15.','Делим обе части на 3: x = 5.','Проверка: 3 × 5 − 7 = 8.')
add(S,'Квадратное уравнение','ОГЭ','Решите уравнение x² − 5x + 6 = 0.','x = 2 или x = 3','Дискриминант: D = (−5)² − 4 × 1 × 6 = 1.','По формуле корней x = (5 ± 1)/2, поэтому x₁ = 2, x₂ = 3.','Проверка разложением: (x − 2)(x − 3) = 0.')
add(S,'Арифметическая прогрессия','ОГЭ','В арифметической прогрессии первые члены равны 7, 10, 13. Найдите десятый член.','34','Разность прогрессии d = 10 − 7 = 3.','Формула aₙ = a₁ + (n − 1)d.','a₁₀ = 7 + 9 × 3 = 34. До десятого члена девять переходов, а не десять.')
add(S,'Теорема Пифагора','ОГЭ','Катеты прямоугольного треугольника равны 6 см и 8 см. Найдите гипотенузу.','10 см','Для прямоугольного треугольника c² = a² + b².','c² = 6² + 8² = 36 + 64 = 100.','Длина положительна, поэтому c = √100 = 10 см. Гипотенуза больше каждого катета.')
add(S,'Среднее арифметическое','ОГЭ','Найдите среднее арифметическое чисел 4, 5, 3, 4, 4.','4','Сумма чисел: 4 + 5 + 3 + 4 + 4 = 20.','Всего чисел пять; среднее равно сумме, делённой на их количество.','20/5 = 4. Все значения имеют одинаковый вес.')
add(S,'Рациональное уравнение','ОГЭ','Решите уравнение (x + 1)/(x − 2) = 2.','x = 5','Область допустимых значений: x ≠ 2, чтобы знаменатель был ненулевым.','Умножаем обе части на x − 2: x + 1 = 2x − 4. Отсюда x = 5.','Корень допустим. Проверка: (5 + 1)/(5 − 2) = 6/3 = 2.')
add(S,'Показательное уравнение','ЕГЭ','Решите уравнение 3^(2x − 1) = 27.','x = 2','Представляем правую часть как степень того же основания: 27 = 3³.','Основание 3 положительно и не равно 1; равенство степеней означает равенство показателей: 2x − 1 = 3.','2x = 4, x = 2. Проверка: 3^(4 − 1) = 27.')
add(S,'Логарифмическое уравнение','ЕГЭ','Решите уравнение log₂(x − 1) + log₂(x + 1) = 3.','x = 3','Область определения: x − 1 > 0 и x + 1 > 0, вместе x > 1.','Объединяем логарифмы: log₂((x − 1)(x + 1)) = 3, поэтому x² − 1 = 8.','Из x² = 9 получаем x = ±3, но область определения удовлетворяет только x = 3. Проверка: log₂2 + log₂4 = 1 + 2 = 3.')
add(S,'Тригонометрическое уравнение','ЕГЭ','Решите уравнение 2 sin x = 1 на всей числовой прямой. Угол дан в радианах.','x = π/6 + 2πk или x = 5π/6 + 2πk, где k — целое число','Делим обе части на 2: sin x = 1/2.','На одном периоде [0; 2π) синус равен 1/2 при x = π/6 и x = 5π/6.','Добавляем ко всем решениям целое число периодов 2πk. Значения в градусах здесь не используются.')
add(S,'Наибольшее и наименьшее значения','ЕГЭ','Найдите наименьшее и наибольшее значения функции f(x) = x³ − 3x на отрезке [−2; 2].','Наименьшее значение −2; наибольшее значение 2','Производная f′(x) = 3x² − 3. Критические точки внутри отрезка: x = −1 и x = 1.','Считаем значения на концах и в критических точках: f(−2) = −2, f(−1) = 2, f(1) = −2, f(2) = 2.','Сравниваем четыре значения: минимум −2, максимум 2. На замкнутом отрезке нельзя забывать о его концах.')
add(S,'Вероятность без возвращения','ЕГЭ','В коробке 5 красных и 3 синих шара. Наугад последовательно извлекают два шара без возвращения. Найдите вероятность, что оба синие.','3/28','Вероятность синего первого шара равна 3/8.','Если первый шар синий, остаётся 2 синих шара из 7; условная вероятность второго синего равна 2/7.','Перемножаем: (3/8) × (2/7) = 6/56 = 3/28. Извлечения зависимы; второй знаменатель не равен 8.')
add(S,'Объём цилиндра','ЕГЭ','Радиус основания цилиндра равен 3 см, высота — 4 см. Найдите его объём.','36π см³','Объём цилиндра V = πr²h.','Площадь основания: π × 3² = 9π см².','Умножаем на высоту: V = 9π × 4 = 36π см³. Ответ точный; радиус не следует путать с диаметром.')
assert len(rows)==56 and len({r['subject'] for r in rows})==11
assert all(len(r['steps'])>=3 for r in rows)
out={'version':1,'notice':'Авторские задания для повторения тем ОГЭ/ЕГЭ. Не официальный банк ФИПИ, не полная программа и не копия экзаменационных вариантов. Метка экзамена указывает уровень подготовки; формат и оценивание реального экзамена могут отличаться.','tasks':rows}
Path(__file__).resolve().parents[1].joinpath('web-source/exam-bank.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(f'Authored offline bank: {len(rows)} tasks / 11 subjects')
